#!/usr/bin/env python3
"""Writes the app's IconPaths.kt from icons.json (run after editing icons.json)."""
import json
import os

here = os.path.dirname(os.path.abspath(__file__))
data = json.load(open(os.path.join(here, "icons.json")))
out = os.path.join(here, "..", "..", "app", "src", "main", "java", "com", "quartz", "notes", "ui", "components", "IconPaths.kt")


def q(s):
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"').replace("$", "\\$") + '"'


lines = [
    "// Generated by shared/icons/generate.py from shared/icons/icons.json. Don't edit by hand.",
    "package com.quartz.notes.ui.components",
    "",
    "/** An icon drawn from 24x24 SVG paths. */",
    "internal class IconPaths(val paths: List<String>, val evenOdd: Boolean = false)",
    "",
    "/** Icons drawn from paths, by key. */",
    "internal val iconPaths: Map<String, IconPaths> = mapOf(",
]
for g in data["groups"]:
    for icon in g["icons"]:
        if "paths" in icon:
            paths = ", ".join(q(p) for p in icon["paths"])
            eo = ", evenOdd = true" if icon.get("evenOdd") else ""
            lines.append(f"    {q(icon['key'])} to IconPaths(listOf({paths}){eo}),")
lines += [")", "", "/** The pickers' groups: title and icon keys, in order. */", "internal val iconGroups: List<Pair<String, List<String>>> = listOf("]
for g in data["groups"]:
    keys = ", ".join(q(i["key"]) for i in g["icons"])
    lines.append(f"    {q(g['title'])} to listOf({keys}),")
lines += [")", ""]
open(out, "w").write("\n".join(lines))
print("wrote", os.path.relpath(out))
